public class TypedSettingsTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void checkCall(String label, Object expected, java.util.concurrent.Callable<Object> call) {
        Object actual;
        try {
            actual = call.call();
        } catch (Throwable t) {
            actual = t.getClass().getSimpleName();
        }
        check(label, expected, actual);
    }

    public static void main(String[] args) {
        TypedSettings settings = new TypedSettings();
        settings.put(String.class, "dark");
        settings.put(Integer.class, 12);

        checkCall("get(String.class) needs no cast", "dark", () -> {
            String theme = settings.get(String.class);
            return theme;
        });
        check("get(Integer.class)", 12, settings.get(Integer.class));
        check("get on an absent type", null, settings.get(Double.class));
        check("getOrDefault on an absent type", 1.5, settings.getOrDefault(Double.class, 1.5));
        check("has(Integer.class)", true, settings.has(Integer.class));
        check("size()", 2, settings.size());

        settings.put(String.class, "light");
        check("re-put replaces rather than grows", 2, settings.size());

        String threw;
        try {
            settings.put((Class<String>) null, "x");
            threw = "nothing";
        } catch (IllegalArgumentException e) {
            threw = "IllegalArgumentException";
        } catch (Throwable t) {
            threw = t.getClass().getSimpleName();
        }
        check("put(null, ...) throws IllegalArgumentException", "IllegalArgumentException", threw);

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

